package com.oneverse.lazers;

import static org.junit.jupiter.api.Assertions.*;
import java.net.URI;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;

class LazersClientTest {
  static final class RecordingTransport implements LazersClient.Transport {
    final List<String> bodies = new CopyOnWriteArrayList<>(); final Queue<Integer> statuses = new ArrayDeque<>(); volatile boolean fail;
    @Override public synchronized int post(URI uri, Map<String,String> headers, byte[] body, Duration timeout) throws Exception { bodies.add(new String(body)); if(fail) throw new java.io.IOException("down"); return statuses.isEmpty()?202:statuses.remove(); }
  }
  LazersClient client(RecordingTransport t) { return LazersClient.builder().apiKey("key").endpoint("https://api.test").projectId("project").environment("production").serviceName("api").retryBaseDelay(Duration.ofMillis(1)).transport(t).build(); }
  @Test void configValidation() { assertThrows(IllegalArgumentException.class, () -> LazersClient.builder().endpoint("x").projectId("p").environment("e").serviceName("s").build()); }
  @Test void enabledFalseDoesNotQueue() { RecordingTransport t=new RecordingTransport(); LazersClient c=LazersClient.builder().apiKey("k").endpoint("x").projectId("p").environment("e").serviceName("s").enabled(false).transport(t).build(); c.captureMessage("no"); assertEquals(0,c.getQueueSize()); c.close(); }
  @Test void protocolAndEventMappings() { RecordingTransport t=new RecordingTransport(); LazersClient c=client(t); c.captureError(new IllegalStateException("bad")); c.flush(); c.captureMessage("hello"); c.flush(); c.captureJobFailure("daily",new RuntimeException("fail")); c.flush(); c.captureWebhookFailure("stripe",new RuntimeException("no")); c.flush(); assertTrue(t.bodies.get(0).contains("\"protocolVersion\":\"1\"")); assertTrue(t.bodies.get(0).contains("\"eventCategory\":\"error\"")); assertTrue(t.bodies.get(1).contains("\"eventCategory\":\"message\"")); assertTrue(t.bodies.get(2).contains("\"eventCategory\":\"job_failure\"")); assertTrue(t.bodies.get(3).contains("\"eventCategory\":\"webhook_failure\"")); c.close(); }
  @Test void redactionAndNormalization() { RecordingTransport t=new RecordingTransport(); LazersClient c=client(t); LazersClient.Context x=new LazersClient.Context().metadata(Map.of("password","x","nested",Map.of("accessToken","y"),"safe","ok")).provider(" Stripe ").eventName(" payment  failed "); c.captureMessage("x",x); c.flush(); String b=t.bodies.get(0); assertTrue(b.contains("[REDACTED]")); assertTrue(b.contains("\"serviceName\":\"api\"")); assertFalse(b.contains("\"password\":\"x\"")); c.close(); }
  @Test void releaseTraceAndCorrelationRules() { RecordingTransport t=new RecordingTransport(); LazersClient c=LazersClient.builder().apiKey("k").endpoint("x").projectId("p").environment("e").serviceName("s").release("unknown").transport(t).build(); c.captureMessage("x"); c.flush(); assertTrue(t.bodies.get(0).matches(".*\\\"traceId\\\":\\\"exec_[^\\\"]+\\\".*")); assertFalse(t.bodies.get(0).contains("correlationId")); assertFalse(t.bodies.get(0).contains("\"release\"")); c.captureMessage("x",new LazersClient.Context().correlationId("flow-1")); c.flush(); assertTrue(t.bodies.get(1).contains("\"correlationId\":\"flow-1\"")); c.close(); }
  @Test void fingerprintIsStableAndExcludesActorAndTrace() { RecordingTransport t=new RecordingTransport(); LazersClient c=client(t); c.captureError(new RuntimeException("same"),new LazersClient.Context().traceId("exec_a").actor(Map.of("type","customer","id","one"))); c.flush(); c.captureError(new RuntimeException("same"),new LazersClient.Context().traceId("exec_b").actor(Map.of("type","customer","id","two"))); c.flush(); assertEquals(field(t.bodies.get(0),"fingerprint"),field(t.bodies.get(1),"fingerprint")); c.close(); }
  @Test void throwableCauseSerialization() { RecordingTransport t=new RecordingTransport(); LazersClient c=client(t); c.captureError(new RuntimeException("outer",new IllegalArgumentException("inner"))); c.flush(); String b=t.bodies.get(0); assertTrue(b.contains("\"name\":\"RuntimeException\"")); assertTrue(b.contains("\"cause\"")); assertTrue(b.contains("IllegalArgumentException")); c.close(); }
  @Test void customProviderFailureAndExplicitFingerprint() { RecordingTransport t=new RecordingTransport(); LazersClient c=client(t); c.captureSignal(new LazersClient.SignalInput("timeout").eventCategory("provider_failure").context(new LazersClient.Context().provider("stripe").fingerprint(" DB Timeout "))); c.flush(); assertTrue(t.bodies.get(0).contains("\"eventCategory\":\"provider_failure\"")); assertTrue(t.bodies.get(0).contains("\"fingerprint\":\"db timeout\"")); c.close(); }
  @Test void queueDropsOldestWhenDeliveryIsBlocked() { RecordingTransport t=new RecordingTransport(); t.fail=true; LazersClient c=LazersClient.builder().apiKey("k").endpoint("x").projectId("p").environment("e").serviceName("s").maxQueueSize(2).maxRetries(5).retryBaseDelay(Duration.ofSeconds(5)).transport(t).build(); c.captureMessage("one"); c.captureMessage("two"); c.captureMessage("three"); assertTrue(c.getQueueSize()<=2); c.close(); }
  @Test void retryAndTerminalClassification() { RecordingTransport t=new RecordingTransport(); t.statuses.add(500);t.statuses.add(202); LazersClient c=client(t); c.captureMessage("retry"); c.flush(); assertTrue(t.bodies.size()>=2); c.close(); RecordingTransport terminal=new RecordingTransport();terminal.statuses.add(401); LazersClient d=client(terminal);d.captureMessage("terminal");d.flush();assertEquals(1,terminal.bodies.size());d.close(); }
  @Test void concurrentCaptureFlushAndClose() throws Exception { RecordingTransport t=new RecordingTransport(); LazersClient c=client(t); List<Thread> threads=new ArrayList<>();for(int i=0;i<12;i++){Thread th=new Thread(()->{for(int n=0;n<15;n++)c.captureMessage("m");});threads.add(th);th.start();}for(Thread th:threads)th.join();c.flush();assertEquals(0,c.getQueueSize());assertFalse(t.bodies.isEmpty());c.close(); }
  @Test void canonicalFixtureCompatibility() { RecordingTransport t=new RecordingTransport(); LazersClient c=client(t); c.captureError(new RuntimeException("Database timeout"));c.flush();c.captureJobFailure("daily-sync",new RuntimeException("sync failed"));c.flush();c.captureWebhookFailure("stripe",new RuntimeException("signature failed"));c.flush();c.captureError(new RuntimeException("actor"),new LazersClient.Context().actor(Map.of("type","customer","id","cust_2048","label","Acme")));c.flush();c.captureSignal(new LazersClient.SignalInput("timeout").eventCategory("provider_failure").context(new LazersClient.Context().provider("stripe")));c.flush(); assertEquals(5,t.bodies.size());assertTrue(t.bodies.get(1).contains("\"id\":\"daily-sync\""));assertTrue(t.bodies.get(2).contains("webhook.failure"));assertTrue(t.bodies.get(3).contains("cust_2048"));c.close(); }
  private static String field(String json,String key){String prefix="\""+key+"\":\"";int start=json.indexOf(prefix)+prefix.length();return json.substring(start,json.indexOf('"',start));}
}